{
  "title": "Prompt builder",
  "description": "Answer the questions, and the cell below writes your prompt.",
  "width": 900,
  "height": 222,
  "controls": [
    { "type": "text", "label": "Topic", "bind": "recipe_topic", "default": "the planets of the Solar System", "placeholder": "What is the notebook about?", "x": 0, "y": 0, "width": 280, "height": 64 },
    {
      "type": "select", "label": "Who it is for", "bind": "recipe_audience", "default": "a class of 12-year-olds",
      "options": ["myself", "a class of 12-year-olds", "my team at work", "complete beginners"],
      "x": 310, "y": 0, "width": 280, "height": 64
    },
    {
      "type": "select", "label": "Where the data comes from", "bind": "recipe_data", "default": "real facts the model knows",
      "options": ["realistic made-up data", "real facts the model knows", "a live public API that needs no key"],
      "x": 620, "y": 0, "width": 280, "height": 64
    },
    { "type": "checkbox", "label": "A chart", "bind": "recipe_chart", "default": true, "x": 0, "y": 86, "width": 280, "height": 42 },
    { "type": "checkbox", "label": "Sliders or other controls", "bind": "recipe_controls", "default": true, "x": 310, "y": 86, "width": 280, "height": 42 },
    { "type": "checkbox", "label": "A live interactive view", "bind": "recipe_live", "default": true, "x": 620, "y": 86, "width": 280, "height": 42 },
    { "type": "checkbox", "label": "A short quiz at the end", "bind": "recipe_quiz", "default": false, "x": 0, "y": 152, "width": 280, "height": 42 },
    { "type": "checkbox", "label": "Explain each step", "bind": "recipe_explain", "default": true, "x": 310, "y": 152, "width": 280, "height": 42 },
    {
      "type": "select", "label": "Languages", "bind": "recipe_languages", "default": "any",
      "options": ["any", "Python and JavaScript", "JavaScript only"],
      "x": 620, "y": 138, "width": 280, "height": 64
    }
  ]
}
